        "handmade": true,
        "maker": "SaskiaSketches",
        "adoption_date": "unknown",
        "backstory": "When I was very, very young, I went to a hardware store with my father. There was a promotion going for something. We walked past a bin of brightly coloured little rabbit plushies that were there for the promotion. I chose a little purple rabbit plush with red embroidered details. I know nothing else, I wish I knew what hardware store it was and what the promotion was for, but alas, I was so young I barely remember anything. This is one of my first memories. Sadly it is followed by another one of my first memories, but this one is much more painful. I went to the dentist and because I was scared, I took Moeder Konijn, Haasje, and Fiepje with me. When we got home, I realised I only had Moeder Konijn and Haasje with me. Fiepje was gone and I never found him again. I was heartbroken and it still hurts to think about. Then, earlier this year I suddenly got the idea to remake him. Because the plush may be gone, but the character still lives in my mind. So I made him a new body and now I have him again. Is it the same plush? Technically no, but it definitely healed a part of me to have him again like this. It’s a ship of Theseus sort of situation.",
