        "handmade": false,
        "maker": "None",
        "adoption_date": "13/09/2020",
        "backstory": "I absolutely fell in love with the pictures from her listing and she was my first big plush in a long, long time and the first of many more to come! I was so frightened my mother would discover her that I hid her underneath all my other plushies whenever she came to visit. Eventually I came clean haha, she never had a clue. Yuannah has been with me through a very difficult period in my life, so it feels like she’s been with me for much longer than she actually has, I cannot imagine my pack without her in it!",
