        "backstory": "When I was a child, my family and I went to a flea market. I found an IKEA bat plushie just like this one, but my father didn't want to let me buy it. The lady who was selling it gave him to me for free because I told my dad I didn't have any bat plushies. Later I was forced to donate him against my will. Then, in 2024, I went to a charity shop and found Castin. His belly was torn open and his stuffing was spilling out. I felt so bad for him, I took him home, patched him up and cleaned him. I choose to believe he's my old one and that he made his way back to me <3",
        "size": "30cm/12in",
        "fabrics": "fleece, neon",
        "softness": "3/10",
        "weight": "7/10",
