        "softness": "4/10",
        "weight": "6/10",
        "floppiness": "8/10",
        "beads": "none",
        "modifications": "I converted him from a puppet to a plush. I removed the cardboard supports from his face, I added stuffing to his face, neck, and chest, I relocated the tag to the back of his leg, I sewed the hole shut, and I thread-sculpted his face.",
